    return MSG_ERROR

from typing import Final

BATAS_DISKON: Final = 0.3

def terapkan_diskon(harga, persentase_diskon):
    if persentase_diskon > BATAS_DISKON:
        persentase_diskon = BATAS_DISKON
    return harga * (1 - persentase_diskon)

from enum import Enum

class StatusPesanan(Enum):
    DIPROSES = 1
    DIKIRIM = 2
    SELESAI = 3

def update_pesanan(status_saat_ini):
    if status_saat_ini == StatusPesanan.DIPROSES:
        return StatusPesanan.DIKIRIM
    elif status_saat_ini == StatusPesanan.DIKIRIM:
        return StatusPesanan.SELESAI
    return 'Pesanan sudah di tahap akhir'

