    READ = 4
    WRITE = 2
    EXECUTE = 1
    izin_user = READ | WRITE
    return ((izin_user & WRITE) != 0, (izin_user & EXECUTE) != 0)

class Vektor2D:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vektor2D(self.x + other.x, self.y + other.y)

def tambah_vektor():
    v1 = Vektor2D(2, 4)
    v2 = Vektor2D(5, 1)
    hasil = v1 + v2
    return (hasil.x, hasil.y)

